-- creaturemodeldata: 2 inserts, 0 updates, 0 deletes
-- Size, collision and sounds of the Human models, with the player model flags (0x804); size, collision and bounds
-- from CoA's rows for these models (below)

DELETE FROM `creaturemodeldata` WHERE `id` IN (@DrakkinMaleModel, @DrakkinFemaleModel);
INSERT INTO `creaturemodeldata` (`id`, `flags`, `model_path`, `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise`)
SELECT @DrakkinMaleModel, 2052, @DrakkinMaleModelPath, `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 49 /* Human male model 49 */
UNION ALL
SELECT @DrakkinFemaleModel, 2052, @DrakkinFemaleModelPath, `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 50 /* Human female model 50 */;

-- Model scale, collision and bounds of CoA's rows
UPDATE `creaturemodeldata` SET `size_class` = 1, `model_scale` = 1, `collision_width` = 0.611111, `collision_height` = 2.031278, `mount_height` = 1.372636, `geo_box_min_x` = -2.374125, `geo_box_min_y` = -1.152168, `geo_box_min_z` = -0.011238, `geo_box_max_x` = 0.888638, `geo_box_max_y` = 1.239756, `geo_box_max_z` = 2.921149, `world_effect_scale` = 1, `attached_effect_scale` = 1, `missile_collision_radius` = 0, `missile_collision_push` = 0, `missile_collision_raise` = 0 WHERE `id` = @DrakkinMaleModel;
UPDATE `creaturemodeldata` SET `size_class` = 1, `model_scale` = 1, `collision_width` = 1.27778, `collision_height` = 1, `mount_height` = 0, `geo_box_min_x` = -0.801059, `geo_box_min_y` = -0.547027, `geo_box_min_z` = -0.007535, `geo_box_max_x` = 0.271461, `geo_box_max_y` = 0.494371, `geo_box_max_z` = 1.47369, `world_effect_scale` = 1, `attached_effect_scale` = 0, `missile_collision_radius` = 1, `missile_collision_push` = 0, `missile_collision_raise` = 0 WHERE `id` = @DrakkinFemaleModel;
